local _K = "kd5sRf03UnCaZ5oyaCYj1zY4"
local _B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function _d(_s)
	_s = _s:gsub("[^" .. _B .. "=]", "")
	local _bits = (_s:gsub(".", function(_c)
		if _c == "=" then return "" end
		local _r, _f = "", (_B:find(_c, 1, true) - 1)
		for _i = 6, 1, -1 do _r = _r .. (_f % 2 ^ _i - _f % 2 ^ (_i - 1) > 0 and "1" or "0") end
		return _r
	end))
	local _out = {}
	for _i = 1, #_bits - 7, 8 do
		local _byte = _bits:sub(_i, _i + 7)
		local _c = 0
		for _j = 1, 8 do _c = _c + (_byte:sub(_j, _j) == "1" and 2 ^ (8 - _j) or 0) end
